script.text:

function load$&Identity;Grid$(g) {
		g.add_itemValueChanged(onChange$GridVoucherDetail$);      
		g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete); 
		g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
		var f = g.get_element().parentForm;
		g._changeReadOnly(true);
}
function scatter$&Identity;Grid$(g) {g._memvars = [];}

function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'Check':
			&ESG.ScriptCheck;
			g.validRowExpression('ma_kh', '(![tk_cn]) || ([ma_kh] != "")');
			break;
				default:
			break;
	}
}



function onChange$GridVoucher$ESG$Expense(o) {o.grid.request(o, 'ESG$Expense', 'ESG$Expense', ['ma_phi'], o.grid.$h, true);}
function onChange$GridVoucher$ESG$Contract(o) {o.grid.request(o, 'ESG$Contract', 'ESG$Contract', ['ma_hd'], o.grid.$h, true);}

function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'ESG$Expense':
			g.setItemGridBehavior(o, [['ma_td2', '', '', null], ['td2_yn', result[0].Value, null, null]]);
			break;
		case 'ESG$Contract':
			g.setItemGridBehavior(o, [['ma_hd_goc', result[1].Value, null, null], ['ma_hd_cha', result[2].Value, null, null], ['hdong_so', result[7].Value, null, null]]);
			if(g._getColumnOrder('s1') != -1) g.setItemGridBehavior(o, [['s1', '', '', null]]);
			if (result[0].Value == 1) {
				g.setItemGridBehavior(o, [['ma_vv', result[3].Value, null, null];
				if (g._voucherCode == 'HD9' || g._voucherCode == 'PN9') g.setItemGridBehavior(o, [['ma_kh', result[5].Value, result[6].Value, null]]);
			}
			break;
		default:
			break;
	}
}

query.text:
declare @$baseCurrency varchar(3) select top 1 @$baseCurrency = rtrim(ltrim(val)) from options where name = 'm_ma_nt0'
select top 0 stt_rec, ngay_ct, ma_nt into #$cttt20 from cttt20 select top 0 stt_rec, ngay_ct, ma_nt into #$cttt30 from cttt30 select top 0 tk into #$ar from dmtk select top 0 tk into #$ap from dmtk
select top 0 @@fieldExternal from @@prime$partition$current a left join dmtk b on a.tk = b.tk left join dmkh c on a.ma_kh = c.ma_kh left join #$cttt20 d on a.stt_rec_tt2 = d.stt_rec left join #$cttt30 e on a.stt_rec_tt3 = e.stt_rec left join #$ar f on a.tk = f.tk left join #$ap g on a.tk = g.tk &ESG.queryLoading;
